<script setup>
import { computed, ref } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import InternalDashboardLayout from '@/Layouts/InternalDashboardLayout.vue';

const props = defineProps({ user: Object, periods: { type: Array, default: () => [] }, selectedPeriod: { type: Object, default: null }, activePeriodId: { type: [Number, String], default: null }, canManageActions: { type: Boolean, default: false } });
const months = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const periodLabel = (p) => p ? `${months[Number(p.bulan) - 1] || p.bulan} ${p.tahun}` : '-';
const history = computed(() => props.periods.filter((p) => Number(p.id) !== Number(props.selectedPeriod?.id)));
const exportingParticipantId = ref(null);
const changePeriod = (event) => router.get(route('dashboard.kpi.index'), { period_id: event.target.value }, { preserveState: false, preserveScroll: true, replace: true });
const exportKpi = (participant) => {
    if (!props.canManageActions || exportingParticipantId.value !== null) return;
    exportingParticipantId.value = participant.id;
    const link = document.createElement('a');
    link.href = route('dashboard.kpi.employee.export', { period: props.selectedPeriod.id, employee: participant.karyawan_id });
    link.setAttribute('download', '');
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => { exportingParticipantId.value = null; }, 1500);
};
const badgeClass = (label) => {
    if (label === 'Dialihkan') return 'bg-emerald-900/10 text-emerald-900';
    if (label === 'Selesai' || label?.endsWith('· Selesai')) return 'bg-emerald-50 text-emerald-700';
    if (['Menunggu Approval','Menunggu TTD'].includes(label)) return 'bg-amber-50 text-amber-700';
    if (['Draft','Siap Dinilai','Siap Finalisasi','Sedang Dinilai'].includes(label)) return 'bg-blue-50 text-blue-700';
    return 'bg-slate-100 text-slate-600';
};
</script>

<template>
    <InternalDashboardLayout title="Monitoring Periode KPI" :user="user" content-width="wide">
        <div class="min-h-[calc(100vh-64px)] w-full bg-[#f5f8fd] px-4 py-5 sm:px-6 lg:px-8">
            <div v-if="!periods.length" class="rounded-2xl border border-[#dce5f1] bg-white p-10 text-center shadow-sm"><h1 class="text-xl font-bold text-[#0b3475]">Belum ada periode KPI</h1><p class="mt-2 text-sm text-slate-500">Periode akan terbentuk setelah snapshot peserta tersedia.</p></div>
            <div v-else-if="selectedPeriod" class="space-y-5">
                <header class="flex flex-col gap-4 rounded-2xl border border-[#dce5f1] bg-white p-6 shadow-sm lg:flex-row lg:items-end lg:justify-between"><div><p class="text-xs font-semibold uppercase tracking-[0.16em] text-[#5273a8]">KPI / Monitoring Siklus</p><h1 class="mt-1 text-3xl font-bold text-[#0b3475]">Monitoring Periode KPI</h1><p class="mt-2 max-w-2xl text-sm text-[#55709f]">Pantau progres KPI, tahap berikutnya, dan masalah yang membutuhkan tindak lanjut.</p></div><label class="w-full text-xs font-semibold text-[#5273a8] lg:w-64">Periode yang dipantau<select class="mt-2 h-11 w-full rounded-lg border-[#cbd8ea] bg-white text-sm font-semibold text-[#173467]" :value="selectedPeriod.id" @change="changePeriod"><option v-for="period in periods" :key="period.id" :value="period.id">{{ periodLabel(period) }}</option></select></label></header>
                <section class="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"><div class="rounded-xl border border-[#dce5f1] bg-white p-4 shadow-sm"><p class="text-xs font-semibold text-slate-500">Peserta KPI</p><strong class="mt-2 block text-2xl text-[#0b3475]">{{ selectedPeriod.summary.participants }}</strong><span class="text-xs text-slate-500">participant periode</span></div><div class="rounded-xl border border-[#dce5f1] bg-white p-4 shadow-sm"><p class="text-xs font-semibold text-slate-500">KPI Selesai</p><strong class="mt-2 block text-2xl text-[#0b3475]">{{ selectedPeriod.summary.completed }} / {{ selectedPeriod.summary.participants }}</strong><span class="text-xs text-slate-500">seluruh tahap sampai Nilai Akhir</span></div><div class="rounded-xl border border-[#dce5f1] bg-white p-4 shadow-sm"><p class="text-xs font-semibold text-slate-500">Perlu Tindakan</p><strong class="mt-2 block text-2xl text-[#0b3475]">{{ selectedPeriod.summary.action }}</strong><span class="text-xs text-slate-500">karyawan/masalah aktual</span></div><div class="rounded-xl border border-[#dce5f1] bg-white p-4 shadow-sm"><p class="text-xs font-semibold text-slate-500">Progress Periode</p><strong class="mt-2 block text-2xl text-[#0b3475]">{{ selectedPeriod.summary.overall_percentage }}%</strong><span class="text-xs text-slate-500">seluruh tahap KPI</span></div></section>
                <section class="rounded-2xl border border-[#dce5f1] bg-white p-5 shadow-sm sm:p-6"><div class="flex flex-col gap-2 border-b border-[#e5ebf3] pb-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="text-xs font-semibold uppercase tracking-[0.14em] text-[#5273a8]">Progress Periode</p><h2 class="mt-1 text-xl font-bold text-[#0b3475]">{{ periodLabel(selectedPeriod) }}</h2></div><span class="text-xs font-semibold text-slate-500">Penilai MPA: {{ selectedPeriod.evaluator_name || 'Belum ditetapkan' }} · {{ selectedPeriod.evaluator_status }}</span></div><div class="mt-5 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3"><div v-for="item in Object.values(selectedPeriod.progress)" :key="item.label" class="rounded-xl border border-[#e1e8f2] bg-[#fbfdff] p-3"><div class="flex items-center justify-between gap-2"><span class="text-sm font-semibold text-[#5273a8]">{{ item.label }}</span><strong class="text-sm text-[#0b3475]">{{ item.complete }} / {{ item.total }}</strong></div><div class="mt-3 h-1.5 overflow-hidden rounded-full bg-[#e7edf6]"><div class="h-full rounded-full bg-[#2867e8]" :style="{ width: `${item.percentage}%` }"></div></div><div class="mt-1 text-right text-[11px] font-semibold text-slate-500">{{ item.percentage }}%</div></div></div></section>
                <section v-if="selectedPeriod.action_items.length" class="rounded-2xl border border-amber-200 bg-amber-50/50 p-5 shadow-sm sm:p-6"><p class="text-xs font-semibold uppercase tracking-[0.14em] text-amber-700">Perlu Tindakan</p><div class="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3"><div v-for="item in selectedPeriod.action_items" :key="item.key" class="rounded-lg border border-amber-200 bg-white px-3 py-2 text-sm text-amber-900"><strong>{{ item.count }}</strong><span class="ml-2">{{ item.label }}</span></div></div></section>
                <section class="rounded-2xl border border-[#dce5f1] bg-white p-5 shadow-sm sm:p-6"><div class="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-xs font-semibold uppercase tracking-[0.14em] text-[#5273a8]">Monitoring Per Karyawan</p><h2 class="mt-1 text-xl font-bold text-[#0b3475]">{{ periodLabel(selectedPeriod) }}</h2></div><span class="text-xs text-slate-500">Daily ditampilkan sebagai selesai / wajib</span></div><div class="mt-5 overflow-x-auto"><table class="min-w-[1280px] w-full text-left text-xs"><thead><tr class="border-b border-[#dce5f1] text-[11px] uppercase tracking-wide text-[#5273a8]"><th class="w-48 px-3 py-3">Karyawan</th><th class="w-28 px-3 py-3">Daily Report</th><th class="w-28 px-3 py-3">KI</th><th class="w-28 px-3 py-3">K-OPS</th><th class="w-32 px-3 py-3">MPA</th><th class="w-32 px-3 py-3">Monthly</th><th class="w-32 px-3 py-3">Nilai Akhir</th><th class="w-24 px-3 py-3">Kategori</th><th class="w-32 px-3 py-3">Menunggu</th><th class="w-48 px-3 py-3">Masalah</th><th v-if="canManageActions" class="w-52 px-3 py-3">Aksi</th></tr></thead><tbody class="divide-y divide-[#edf1f7]"><tr v-for="participant in selectedPeriod.participants" :key="participant.id" class="hover:bg-[#fbfdff]"><td class="px-3 py-3"><span class="font-semibold text-[#173467]">{{ participant.nama }}</span><span class="mt-1 block text-slate-500">{{ participant.jabatan }}</span></td><td class="px-3 py-3"><span class="font-semibold" :class="participant.daily.complete ? 'text-emerald-700' : 'text-[#173467]'">{{ participant.daily.completed }} / {{ participant.daily.required }}</span><span class="mt-1 block text-[11px] text-slate-500">{{ participant.daily.complete ? 'Selesai' : 'Belum selesai' }}</span></td><td class="px-3 py-3"><span class="rounded-full px-2 py-1 font-semibold" :class="badgeClass(participant.individual_status)">{{ participant.individual_status }}</span></td><td class="px-3 py-3"><span class="rounded-full px-2 py-1 font-semibold" :class="badgeClass(participant.ops_status)">{{ participant.ops_status }}</span></td><td class="px-3 py-3"><span class="rounded-full px-2 py-1 font-semibold" :class="badgeClass(participant.mpa_status)">{{ participant.mpa_status }}</span></td><td class="px-3 py-3"><span class="rounded-full px-2 py-1 font-semibold" :class="badgeClass(participant.monthly_status)">{{ participant.monthly_status }}</span></td><td class="px-3 py-3"><span class="rounded-full px-2 py-1 font-semibold" :class="badgeClass(participant.final_status)">{{ participant.final_status }}</span></td><td class="px-3 py-3 font-semibold text-[#173467]">{{ participant.category }}</td><td class="px-3 py-3 font-semibold" :class="participant.waiting_for === 'Selesai' ? 'text-emerald-700' : 'text-[#173467]'">{{ participant.waiting_for }}</td><td class="px-3 py-3"><span v-if="participant.problems.length" class="text-rose-600">{{ participant.problems.join(', ') }}</span><span v-else class="text-slate-400">—</span></td><td v-if="canManageActions" class="px-3 py-3"><div class="flex flex-wrap gap-2"><Link :href="participant.detail_url" class="rounded-lg bg-[#1463e8] px-3 py-2 text-[11px] font-bold text-white hover:bg-[#0b55c8]">Detail KPI</Link><button type="button" :disabled="exportingParticipantId === participant.id" @click="exportKpi(participant)" class="inline-flex items-center gap-1.5 rounded-lg border border-[#1463e8] px-3 py-2 text-[11px] font-bold text-[#1463e8] hover:bg-[#edf4ff] disabled:cursor-wait disabled:opacity-60"><svg aria-hidden="true" class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3v12m0 0 4-4m-4 4-4-4M5 21h14" stroke-linecap="round" stroke-linejoin="round"/></svg>{{ exportingParticipantId === participant.id ? 'Menyiapkan...' : 'Export KPI' }}</button></div></td></tr><tr v-if="!selectedPeriod.participants.length"><td :colspan="canManageActions ? 11 : 10" class="px-3 py-10 text-center text-slate-500">Belum tersedia peserta pada periode ini.</td></tr></tbody></table></div></section>
                <section class="rounded-2xl border border-[#dce5f1] bg-white p-5 shadow-sm sm:p-6"><div class="flex items-center justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-[0.14em] text-[#5273a8]">Riwayat Periode KPI</p><h2 class="mt-1 text-xl font-bold text-[#0b3475]">Siklus sebelumnya</h2></div><span class="text-xs text-slate-500">{{ history.length }} periode</span></div><div v-if="history.length" class="mt-4 space-y-3"><div v-for="period in history" :key="period.id" class="flex flex-col gap-3 rounded-xl border border-[#e1e8f2] p-4 sm:flex-row sm:items-center sm:justify-between"><div><strong class="text-sm text-[#173467]">{{ periodLabel(period) }}</strong><span class="mt-1 block text-xs text-slate-500">{{ period.summary.completed }} / {{ period.summary.participants }} KPI selesai · {{ period.summary.overall_percentage }}%</span></div><Link :href="route('dashboard.kpi.index', { period_id: period.id })" class="w-fit rounded-lg border border-[#b8ccee] px-3 py-2 text-xs font-bold text-[#1463e8] hover:bg-[#edf4ff]">Lihat periode</Link></div></div><div v-else class="mt-4 rounded-xl border border-dashed border-[#cbd8ea] p-7 text-center text-sm text-slate-500">Belum ada periode sebelumnya.</div></section>
            </div>
        </div>
    </InternalDashboardLayout>
</template>
